'use strict';

/**
 * db.js — PostgreSQL connection pool module
 *
 * Loads DATABASE_URL from .env.test (via dotenv) and exposes:
 *   pool      — the shared pg.Pool instance
 *   query()   — thin wrapper around pool.query()
 *   healthCheck() — verifies the pool can reach the database
 *   close()   — gracefully drains and closes the pool
 */

const path = require('path');
const { Pool } = require('pg');

// ---------------------------------------------------------------------------
// 1. Load environment variables from .env.test
//    dotenv.config() is a no-op when a key is already present in process.env,
//    so it is safe to call unconditionally.
// ---------------------------------------------------------------------------
require('dotenv').config({ path: path.resolve(__dirname, '.env.test') });

const DATABASE_URL = process.env.DATABASE_URL;

if (!DATABASE_URL) {
  throw new Error(
    '[db] DATABASE_URL is not defined. ' +
    'Ensure .env.test exists and contains a valid DATABASE_URL entry.'
  );
}

// ---------------------------------------------------------------------------
// 2. Pool configuration
//    All values are tunable via environment variables so the same module works
//    across local, CI, and staging environments without code changes.
// ---------------------------------------------------------------------------
const POOL_CONFIG = {
  connectionString: DATABASE_URL,

  // Maximum number of clients in the pool (default pg value is 10)
  max: parseInt(process.env.DB_POOL_MAX ?? '10', 10),

  // Milliseconds a client must sit idle before being closed and removed
  idleTimeoutMillis: parseInt(process.env.DB_IDLE_TIMEOUT_MS ?? '30000', 10),

  // Milliseconds to wait for a connection before throwing an error
  connectionTimeoutMillis: parseInt(process.env.DB_CONNECT_TIMEOUT_MS ?? '5000', 10),

  // Keep the connection alive over long-lived pool lifetimes
  keepAlive: true,
};

// ---------------------------------------------------------------------------
// 3. Create the pool
// ---------------------------------------------------------------------------
const pool = new Pool(POOL_CONFIG);

// ---------------------------------------------------------------------------
// 4. Pool-level error handler
//    Without this listener an idle-client error would be an unhandled
//    exception and crash the process.
// ---------------------------------------------------------------------------
pool.on('error', (err, client) => {
  console.error(
    '[db] Unexpected error on idle PostgreSQL client. ' +
    `Client: ${client?.processID ?? 'unknown'} | Error: ${err.message}`
  );
});

pool.on('connect', (client) => {
  console.log(
    `[db] New client connected. ` +
    `Pool total=${pool.totalCount} idle=${pool.idleCount} waiting=${pool.waitingCount}`
  );
});

pool.on('remove', () => {
  console.log(
    `[db] Client removed from pool. ` +
    `Pool total=${pool.totalCount} idle=${pool.idleCount} waiting=${pool.waitingCount}`
  );
});

// ---------------------------------------------------------------------------
// 5. query() — convenience wrapper
//    Accepts the same arguments as pool.query() so callers are not coupled to
//    the pool object directly.
//
//    Usage:
//      const { rows } = await db.query('SELECT $1::text AS msg', ['hello']);
// ---------------------------------------------------------------------------
async function query(text, params) {
  const start = Date.now();

  try {
    const result = await pool.query(text, params);
    const duration = Date.now() - start;

    console.log('[db] Executed query', {
      text,
      duration: `${duration}ms`,
      rowCount: result.rowCount,
    });

    return result;
  } catch (err) {
    console.error('[db] Query failed', {
      text,
      error: err.message,
      code: err.code,          // PostgreSQL error code, e.g. '23505' for unique violation
      duration: `${Date.now() - start}ms`,
    });
    throw err;                  // Re-throw so callers can handle domain errors
  }
}

// ---------------------------------------------------------------------------
// 6. healthCheck() — verifies a round-trip to the database is possible
//    Returns an object so callers (e.g. an /health HTTP endpoint) can include
//    timing and pool-state details in a response payload.
//
//    Usage:
//      const health = await db.healthCheck();
//      // { status: 'healthy', latencyMs: 4, pool: { total:1, idle:1, waiting:0 } }
// ---------------------------------------------------------------------------
async function healthCheck() {
  const start = Date.now();

  try {
    await pool.query('SELECT 1');
    const latencyMs = Date.now() - start;

    return {
      status: 'healthy',
      latencyMs,
      pool: {
        total: pool.totalCount,
        idle: pool.idleCount,
        waiting: pool.waitingCount,
      },
    };
  } catch (err) {
    const latencyMs = Date.now() - start;

    console.error('[db] Health check failed:', err.message);

    return {
      status: 'unhealthy',
      latencyMs,
      error: err.message,
      code: err.code,
      pool: {
        total: pool.totalCount,
        idle: pool.idleCount,
        waiting: pool.waitingCount,
      },
    };
  }
}

// ---------------------------------------------------------------------------
// 7. close() — graceful shutdown
//    Call this during process termination (SIGTERM/SIGINT) to allow in-flight
//    queries to finish before the process exits.
//
//    Usage:
//      process.on('SIGTERM', async () => { await db.close(); process.exit(0); });
// ---------------------------------------------------------------------------
async function close() {
  console.log('[db] Draining and closing connection pool…');
  await pool.end();
  console.log('[db] Connection pool closed.');
}

// ---------------------------------------------------------------------------
// 8. Exports
// ---------------------------------------------------------------------------
module.exports = {
  pool,         // Raw pool — use only when you need manual client checkout
  query,        // Preferred query interface for simple statements
  healthCheck,  // Database reachability probe
  close,        // Graceful-shutdown helper
};

