/**
 * db.js — PostgreSQL connection pool module
 *
 * Reads DATABASE_URL from the environment at runtime.
 * Load your .env.test file BEFORE requiring this module, e.g.:
 *
 *   require('dotenv').config({ path: '.env.test' });
 *   const db = require('./db');
 *
 * Never hard-code credentials here or in source control.
 */

'use strict';

const { Pool } = require('pg');

// ---------------------------------------------------------------------------
// Validate that the required environment variable is present at startup.
// Failing fast here is intentional: a missing DATABASE_URL means every query
// would fail anyway, so it is better to surface the problem immediately.
// ---------------------------------------------------------------------------
const DATABASE_URL = process.env.DATABASE_URL;

if (!DATABASE_URL) {
  throw new Error(
    '[db] DATABASE_URL is not set. ' +
    'Load your environment file before requiring this module.'
  );
}

// ---------------------------------------------------------------------------
// Pool configuration
//
// All tuneable values are read from the environment so that different
// deployment environments (test, staging, production) can override them
// without touching source code.
// ---------------------------------------------------------------------------
const pool = new Pool({
  connectionString: DATABASE_URL,

  // Maximum number of clients in the pool (default: 10).
  max: parseInt(process.env.DB_POOL_MAX ?? '10', 10),

  // Milliseconds a client must sit idle before being closed (default: 30 s).
  idleTimeoutMillis: parseInt(process.env.DB_IDLE_TIMEOUT_MS ?? '30000', 10),

  // Milliseconds to wait for a connection before throwing (default: 5 s).
  connectionTimeoutMillis: parseInt(process.env.DB_CONNECT_TIMEOUT_MS ?? '5000', 10),

  // Keep SSL flexible: set DB_SSL=true in production environments.
  ssl: process.env.DB_SSL === 'true' ? { rejectUnauthorized: true } : false,
});

// ---------------------------------------------------------------------------
// Pool-level error handler
//
// 'error' events on idle clients (e.g. the server closed the connection) are
// emitted on the pool.  Without this listener the process would crash with an
// unhandled error.
// ---------------------------------------------------------------------------
pool.on('error', (err, client) => {
  console.error('[db] Unexpected error on idle client:', err.message);
  // Do NOT re-throw; crashing the whole process over a transient idle-client
  // error is usually undesirable.  The pool will create a fresh client on the
  // next request.
});

pool.on('connect', () => {
  console.log('[db] New client connected to the pool.');
});

pool.on('remove', () => {
  console.log('[db] Client removed from the pool.');
});

// ---------------------------------------------------------------------------
// query — thin wrapper that provides consistent error logging.
// ---------------------------------------------------------------------------

/**
 * Execute a parameterised SQL query using a pool client.
 *
 * @param {string}  text    - Parameterised SQL string, e.g. 'SELECT $1::text'
 * @param {Array}   [params] - Positional parameter values
 * @returns {Promise<import('pg').QueryResult>}
 *
 * @example
 * const { rows } = await db.query('SELECT id, name FROM users WHERE id = $1', [42]);
 */
async function query(text, params) {
  const start = Date.now();

  try {
    const result = await pool.query(text, params);
    const duration = Date.now() - start;
    console.log(`[db] query executed in ${duration}ms — rows: ${result.rowCount}`);
    return result;
  } catch (err) {
    console.error('[db] Query error:', {
      message: err.message,
      query: text,
      // Intentionally omit `params` from logs to avoid leaking sensitive data.
    });
    throw err;
  }
}

// ---------------------------------------------------------------------------
// getClient — borrow a dedicated client for transactions.
// ---------------------------------------------------------------------------

/**
 * Borrow a dedicated client from the pool for use in a transaction.
 * You MUST call `client.release()` when you are done, even on error.
 *
 * @returns {Promise<import('pg').PoolClient>}
 *
 * @example
 * const client = await db.getClient();
 * try {
 *   await client.query('BEGIN');
 *   await client.query('INSERT INTO orders ...');
 *   await client.query('COMMIT');
 * } catch (err) {
 *   await client.query('ROLLBACK');
 *   throw err;
 * } finally {
 *   client.release();
 * }
 */
async function getClient() {
  try {
    const client = await pool.connect();
    return client;
  } catch (err) {
    console.error('[db] Failed to acquire a client from the pool:', err.message);
    throw err;
  }
}

// ---------------------------------------------------------------------------
// healthCheck — verify the pool can reach the database.
// ---------------------------------------------------------------------------

/**
 * Perform a lightweight round-trip to verify database connectivity.
 *
 * Returns a structured result object rather than throwing so that callers
 * (e.g. an HTTP /health endpoint) can handle degraded states gracefully.
 *
 * @returns {Promise<{
 *   healthy: boolean,
 *   timestamp: string,
 *   responseTimeMs: number,
 *   serverVersion?: string,
 *   pool: { total: number, idle: number, waiting: number },
 *   error?: string
 * }>}
 *
 * @example
 * app.get('/health/db', async (req, res) => {
 *   const status = await db.healthCheck();
 *   res.status(status.healthy ? 200 : 503).json(status);
 * });
 */
async function healthCheck() {
  const start = Date.now();

  // Pool metrics are always available, even when the DB is unreachable.
  const poolStats = {
    total: pool.totalCount,
    idle: pool.idleCount,
    waiting: pool.waitingCount,
  };

  try {
    const result = await pool.query('SELECT version(), NOW() AS server_time');
    const responseTimeMs = Date.now() - start;
    const { version } = result.rows[0];

    return {
      healthy: true,
      timestamp: new Date().toISOString(),
      responseTimeMs,
      // Extract only the short version string, e.g. "PostgreSQL 15.3"
      serverVersion: version.split(' on ')[0],
      pool: poolStats,
    };
  } catch (err) {
    const responseTimeMs = Date.now() - start;
    console.error('[db] Health check failed:', err.message);

    return {
      healthy: false,
      timestamp: new Date().toISOString(),
      responseTimeMs,
      pool: poolStats,
      error: err.message,
    };
  }
}

// ---------------------------------------------------------------------------
// shutdown — gracefully drain the pool (call on SIGTERM / SIGINT).
// ---------------------------------------------------------------------------

/**
 * Gracefully close all pool clients.
 * Call this during application shutdown to avoid leaving open connections.
 *
 * @returns {Promise<void>}
 */
async function shutdown() {
  console.log('[db] Draining connection pool…');
  await pool.end();
  console.log('[db] All pool clients have been closed.');
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------
module.exports = {
  query,
  getClient,
  healthCheck,
  shutdown,
  // Expose the raw pool for advanced use-cases (e.g. pgBoss, Knex migration).
  pool,
};

