/**
 * db.js — PostgreSQL connection pool module
 *
 * Loads DATABASE_URL from .env.test (via dotenv) and exposes a
 * configured pg.Pool instance, a graceful shutdown helper, and a
 * healthCheck() function that verifies live connectivity.
 *
 * Usage:
 *   const { pool, healthCheck, closePool } = require('./db');
 *   const result = await pool.query('SELECT now()');
 *   const status = await healthCheck();
 *   await closePool();           // call on process exit / test teardown
 */

'use strict';

const path = require('path');
const { Pool } = require('pg');

// ---------------------------------------------------------------------------
// 1. Load environment variables from .env.test
//    dotenv.config() is a no-op when a key is already present in process.env,
//    so this is safe to call even when the environment is pre-populated (e.g.
//    in CI pipelines that inject secrets directly).
// ---------------------------------------------------------------------------
const dotenv = require('dotenv');

const envResult = dotenv.config({ path: path.resolve(__dirname, '.env.test') });

if (envResult.error) {
  // Not a fatal error — the variable may already exist in the environment.
  console.warn(
    '[db] Warning: could not parse .env.test file:',
    envResult.error.message
  );
}

// ---------------------------------------------------------------------------
// 2. Validate that DATABASE_URL is present before building the pool.
//    Fail loudly at startup rather than with a cryptic error on first query.
// ---------------------------------------------------------------------------
const { DATABASE_URL } = process.env;

if (!DATABASE_URL) {
  throw new Error(
    '[db] DATABASE_URL is not defined. ' +
    'Ensure .env.test exists and contains a valid DATABASE_URL entry.'
  );
}

// ---------------------------------------------------------------------------
// 3. Pool configuration
//
//    connectionString — parsed from DATABASE_URL; contains host, port,
//                       database name, user and password in one place.
//    max              — upper bound on simultaneous client checkouts.
//    idleTimeoutMillis— how long an idle client may remain in the pool
//                       before being evicted and closed.
//    connectionTimeoutMillis — how long pool.connect() will wait for a
//                       free client before rejecting with an error.
//    ssl              — honour the ?sslmode= query parameter that may be
//                       embedded in DATABASE_URL; fall back to requiring
//                       TLS in production (NODE_ENV === 'production') so
//                       that test environments can connect without certs.
// ---------------------------------------------------------------------------
const isProduction = process.env.NODE_ENV === 'production';

const poolConfig = {
  connectionString: DATABASE_URL,
  max: parseInt(process.env.DB_POOL_MAX ?? '10', 10),
  idleTimeoutMillis: parseInt(process.env.DB_IDLE_TIMEOUT_MS ?? '30000', 10),
  connectionTimeoutMillis: parseInt(process.env.DB_CONNECT_TIMEOUT_MS ?? '5000', 10),
  // In production enforce SSL; in other environments allow plain connections
  // unless the URL itself already contains sslmode=require.
  ssl: isProduction ? { rejectUnauthorized: true } : false,
};

// ---------------------------------------------------------------------------
// 4. Create the pool
// ---------------------------------------------------------------------------
const pool = new Pool(poolConfig);

// ---------------------------------------------------------------------------
// 5. Pool-level error handler
//
//    pg emits 'error' on the pool object when a client encounters a network
//    error while idle (e.g. the server closes the connection). Without this
//    listener Node.js would throw an unhandled 'error' event and crash the
//    process. We log it and let the pool automatically replace the client.
// ---------------------------------------------------------------------------
pool.on('error', (err, client) => {
  console.error('[db] Unexpected error on idle PostgreSQL client:', err.message);
  // Do NOT re-throw — the pool will evict and replace the faulted client.
});

// ---------------------------------------------------------------------------
// 6. Connection event logging (helpful for diagnosing pool exhaustion)
// ---------------------------------------------------------------------------
pool.on('connect', () => {
  console.log(
    `[db] New client connected to the pool (total: ${pool.totalCount}, ` +
    `idle: ${pool.idleCount}, waiting: ${pool.waitingCount})`
  );
});

pool.on('remove', () => {
  console.log(
    `[db] Client removed from pool (total: ${pool.totalCount}, ` +
    `idle: ${pool.idleCount}, waiting: ${pool.waitingCount})`
  );
});

// ---------------------------------------------------------------------------
// 7. healthCheck()
//
//    Acquires a dedicated client from the pool, runs a lightweight
//    round-trip query (SELECT 1), then releases the client.
//    Returns a structured object so callers can embed it in an HTTP
//    /health endpoint without extra work.
//
//    Resolves:
//      { healthy: true,  responseTimeMs: <number>, serverTimestamp: <Date> }
//    Rejects (or resolves with healthy:false when allowThrow is false):
//      { healthy: false, responseTimeMs: <number>, error: <string> }
// ---------------------------------------------------------------------------
async function healthCheck({ allowThrow = false } = {}) {
  const start = Date.now();
  let client;

  try {
    client = await pool.connect();

    // SELECT 1 is the canonical no-op connectivity probe; SELECT NOW() gives
    // us the server clock for drift detection as a bonus.
    const { rows } = await client.query(
      'SELECT 1 AS ping, NOW() AS server_timestamp'
    );

    const responseTimeMs = Date.now() - start;

    return {
      healthy: true,
      responseTimeMs,
      serverTimestamp: rows[0].server_timestamp,
      poolStats: {
        total: pool.totalCount,
        idle: pool.idleCount,
        waiting: pool.waitingCount,
      },
    };
  } catch (err) {
    const responseTimeMs = Date.now() - start;

    console.error('[db] Health check failed:', err.message);

    const result = {
      healthy: false,
      responseTimeMs,
      error: err.message,
      poolStats: {
        total: pool.totalCount,
        idle: pool.idleCount,
        waiting: pool.waitingCount,
      },
    };

    if (allowThrow) throw Object.assign(new Error(err.message), result);
    return result;
  } finally {
    // Always release the client back to the pool, even on error.
    if (client) client.release();
  }
}

// ---------------------------------------------------------------------------
// 8. closePool()
//
//    Drains the pool gracefully: waits for all checked-out clients to finish
//    their current query before closing connections. Call this during
//    process shutdown or after each test suite to prevent open handle warnings.
// ---------------------------------------------------------------------------
async function closePool() {
  try {
    await pool.end();
    console.log('[db] Connection pool closed.');
  } catch (err) {
    console.error('[db] Error while closing the pool:', err.message);
    throw err;
  }
}

// ---------------------------------------------------------------------------
// 9. Graceful shutdown on process signals
//
//    Registers handlers for SIGINT (Ctrl-C) and SIGTERM (Docker / systemd)
//    so the pool is drained cleanly without a separate shutdown call in
//    every consumer.  The handlers are registered only once via a flag to
//    avoid duplicate listeners when the module is re-evaluated in tests.
// ---------------------------------------------------------------------------
if (!global.__dbShutdownRegistered) {
  global.__dbShutdownRegistered = true;

  const shutdown = async (signal) => {
    console.log(`[db] Received ${signal}. Closing pool…`);
    await closePool();
    process.exit(0);
  };

  process.once('SIGINT', () => shutdown('SIGINT'));
  process.once('SIGTERM', () => shutdown('SIGTERM'));
}

// ---------------------------------------------------------------------------
// 10. Exports
// ---------------------------------------------------------------------------
module.exports = {
  /**
   * The underlying pg.Pool instance.
   * Use pool.query() for one-shot queries or pool.connect() when you need
   * a transaction spanning multiple statements.
   */
  pool,

  /**
   * Runs a lightweight round-trip to the database and returns connectivity
   * and timing metadata.
   * @param  {{ allowThrow?: boolean }} [options]
   * @returns {Promise<{healthy:boolean, responseTimeMs:number, ...}>}
   */
  healthCheck,

  /**
   * Gracefully drains and closes all pool connections.
   * Should be called on process exit and after each test suite.
   * @returns {Promise<void>}
   */
  closePool,
};

