/**
 * db.js — PostgreSQL connection pool module
 *
 * Reads DATABASE_URL from .env.test (via dotenv) and exposes:
 *   pool        — the pg Pool instance for direct query use
 *   query()     — a thin wrapper around pool.query()
 *   healthCheck() — verifies the database is reachable
 *   closePool() — gracefully shuts the pool down
 */

'use strict';

const path = require('path');
const { Pool } = require('pg');

// ---------------------------------------------------------------------------
// 1. Load environment variables from .env.test
//    dotenv.config() is a no-op for keys that are already set in process.env,
//    so this is safe to call in any environment without overriding CI secrets.
// ---------------------------------------------------------------------------
const dotenv = require('dotenv');
const envResult = dotenv.config({ path: path.resolve(__dirname, '.env.test') });

if (envResult.error) {
  // The file is missing or unreadable — warn but don't crash at import time
  // so that callers can decide how to handle a missing config.
  console.warn(
    '[db] Warning: could not load .env.test —',
    envResult.error.message
  );
}

// ---------------------------------------------------------------------------
// 2. Validate that the required variable is present before creating the pool.
// ---------------------------------------------------------------------------
const { DATABASE_URL } = process.env;

if (!DATABASE_URL) {
  throw new Error(
    '[db] DATABASE_URL is not defined. ' +
    'Ensure .env.test exists and contains a valid DATABASE_URL.'
  );
}

// ---------------------------------------------------------------------------
// 3. Create the connection pool.
//
//    Pool configuration reference:
//      max            — maximum number of clients in the pool (default: 10)
//      idleTimeoutMillis — how long a client may sit idle before being closed
//      connectionTimeoutMillis — how long to wait when acquiring a client
//      allowExitOnIdle — allow the Node process to exit even if the pool is open
// ---------------------------------------------------------------------------
const pool = new Pool({
  connectionString: DATABASE_URL,
  max: 10,
  idleTimeoutMillis: 30_000,   // 30 s
  connectionTimeoutMillis: 5_000, // 5 s
  allowExitOnIdle: true,
});

// ---------------------------------------------------------------------------
// 4. Pool-level error handler.
//
//    Without this listener an idle-client error would be an unhandled
//    EventEmitter exception and crash the process.
// ---------------------------------------------------------------------------
pool.on('error', (err, client) => {
  console.error('[db] Unexpected error on idle client:', err.message);
  // Do not re-throw — the pool will remove the broken client automatically.
});

pool.on('connect', () => {
  // Fired once per new physical connection; useful for debug logging.
  console.log('[db] New client connected to the pool.');
});

pool.on('remove', () => {
  console.log('[db] Client removed from the pool.');
});

// ---------------------------------------------------------------------------
// 5. query() — convenience wrapper so callers never touch the pool directly.
//
//    Usage:
//      const { rows } = await query('SELECT $1::text AS msg', ['hello']);
//
//    The pool automatically acquires a client, runs the query, and releases
//    the client back — no manual client.release() needed.
// ---------------------------------------------------------------------------
async function query(text, params) {
  const start = Date.now();
  try {
    const result = await pool.query(text, params);
    const duration = Date.now() - start;
    console.log('[db] Executed query:', {
      text: text.replace(/\s+/g, ' ').trim(),
      duration: `${duration}ms`,
      rowCount: result.rowCount,
    });
    return result;
  } catch (err) {
    console.error('[db] Query error:', {
      text: text.replace(/\s+/g, ' ').trim(),
      error: err.message,
    });
    throw err; // Re-throw so the caller can handle it
  }
}

// ---------------------------------------------------------------------------
// 6. healthCheck() — verifies the database is reachable.
//
//    Returns an object shaped as:
//      { healthy: true,  message: '...', responseTimeMs: 4  }
//      { healthy: false, message: '...', responseTimeMs: 12, error: '...' }
//
//    This can be wired directly into an Express /health route:
//      app.get('/health/db', async (req, res) => {
//        const check = await healthCheck();
//        res.status(check.healthy ? 200 : 503).json(check);
//      });
// ---------------------------------------------------------------------------
async function healthCheck() {
  const start = Date.now();
  try {
    const result = await pool.query('SELECT 1 AS alive');
    const responseTimeMs = Date.now() - start;

    const isAlive = result.rows[0]?.alive === 1;
    if (!isAlive) {
      throw new Error('Unexpected response from database health query.');
    }

    return {
      healthy: true,
      message: 'Database connection is healthy.',
      responseTimeMs,
      poolStats: getPoolStats(),
    };
  } catch (err) {
    const responseTimeMs = Date.now() - start;
    console.error('[db] Health check failed:', err.message);
    return {
      healthy: false,
      message: 'Database connection check failed.',
      responseTimeMs,
      error: err.message,
      poolStats: getPoolStats(),
    };
  }
}

// ---------------------------------------------------------------------------
// 7. getPoolStats() — snapshot of live pool metrics (no async I/O).
// ---------------------------------------------------------------------------
function getPoolStats() {
  return {
    totalCount: pool.totalCount,   // all clients (idle + active + pending)
    idleCount: pool.idleCount,     // clients waiting for a query
    waitingCount: pool.waitingCount, // queries waiting for a free client
  };
}

// ---------------------------------------------------------------------------
// 8. closePool() — graceful shutdown.
//
//    Call this in your process shutdown handler so in-flight queries finish:
//      process.on('SIGTERM', async () => {
//        await closePool();
//        process.exit(0);
//      });
// ---------------------------------------------------------------------------
async function closePool() {
  try {
    await pool.end();
    console.log('[db] Connection pool closed gracefully.');
  } catch (err) {
    console.error('[db] Error while closing the pool:', err.message);
    throw err;
  }
}

// ---------------------------------------------------------------------------
// Exports
// ---------------------------------------------------------------------------
module.exports = {
  pool,       // raw Pool — use only when you need a dedicated client (transactions)
  query,      // ✅ preferred for simple queries
  healthCheck,
  getPoolStats,
  closePool,
};

