/**
 * db.js — PostgreSQL connection pool module
 *
 * Reads DATABASE_URL at *runtime* from the environment.
 * To load a local env file, call `loadEnv(path)` before importing this module,
 * or set DATABASE_URL in the process environment through another means.
 *
 * Credentials are NEVER hard-coded here; they are always resolved from
 * process.env at the moment the pool is first created.
 */

'use strict';

const { Pool } = require('pg');
const path = require('path');
const fs = require('fs');

// ---------------------------------------------------------------------------
// Environment loader
// ---------------------------------------------------------------------------

/**
 * Minimal, dependency-light .env file parser.
 * Reads key=value pairs into process.env without overwriting existing values.
 * Supports:
 *   - Blank lines and # comments
 *   - Optional surrounding quotes (single or double)
 *   - Inline comments after quoted values
 *
 * @param {string} envFilePath - Absolute or relative path to the .env file.
 * @returns {{ loaded: boolean, path: string, error?: string }}
 */
function loadEnv(envFilePath = path.resolve(process.cwd(), '.env.test')) {
  const absolutePath = path.resolve(envFilePath);

  if (!fs.existsSync(absolutePath)) {
    return { loaded: false, path: absolutePath, error: 'File not found' };
  }

  try {
    const raw = fs.readFileSync(absolutePath, 'utf8');
    let count = 0;

    for (const rawLine of raw.split('\n')) {
      const line = rawLine.trim();

      // Skip blank lines and comments
      if (!line || line.startsWith('#')) continue;

      const eqIndex = line.indexOf('=');
      if (eqIndex === -1) continue;

      const key = line.slice(0, eqIndex).trim();
      let value = line.slice(eqIndex + 1).trim();

      // Strip optional surrounding quotes and inline comments
      const quoteMatch = value.match(/^(['"])([\s\S]*?)\1/);
      if (quoteMatch) {
        value = quoteMatch[2];
      } else {
        // Remove trailing inline comment  (e.g.  value  # comment)
        const commentIdx = value.indexOf(' #');
        if (commentIdx !== -1) value = value.slice(0, commentIdx).trim();
      }

      // Never overwrite a value that was already set (e.g. by CI/CD)
      if (!Object.prototype.hasOwnProperty.call(process.env, key)) {
        process.env[key] = value;
        count++;
      }
    }

    return { loaded: true, path: absolutePath, varsLoaded: count };
  } catch (err) {
    return { loaded: false, path: absolutePath, error: err.message };
  }
}

// ---------------------------------------------------------------------------
// Pool factory
// ---------------------------------------------------------------------------

/** @type {Pool | null} */
let pool = null;

/**
 * Returns the singleton Pool instance, creating it on first call.
 * Throws clearly if DATABASE_URL is missing so the misconfiguration is
 * obvious rather than silent.
 *
 * Pool tuning defaults (all overridable via options):
 *   max             20   – maximum connections kept open
 *   idleTimeoutMs 30000  – close idle connections after 30 s
 *   connectTimeout 5000  – abort a new connection attempt after 5 s
 *
 * @param {object}  [options]
 * @param {number}  [options.max=20]
 * @param {number}  [options.idleTimeoutMillis=30000]
 * @param {number}  [options.connectionTimeoutMillis=5000]
 * @param {boolean} [options.ssl]             - Force SSL (defaults to true when
 *                                              host is not localhost/127.0.0.1)
 * @returns {Pool}
 */
function createPool(options = {}) {
  if (pool) return pool;

  const databaseUrl = process.env.DATABASE_URL;

  if (!databaseUrl || databaseUrl.trim() === '') {
    throw new Error(
      '[db] DATABASE_URL is not set. ' +
        'Call loadEnv() before createPool(), or export DATABASE_URL in the ' +
        'process environment.',
    );
  }

  // Infer whether SSL should be enabled from the host portion of the URL
  let useSsl = options.ssl;
  if (useSsl === undefined) {
    try {
      const { hostname } = new URL(databaseUrl);
      useSsl = hostname !== 'localhost' && hostname !== '127.0.0.1';
    } catch {
      useSsl = false; // malformed URL — let pg surface its own error
    }
  }

  pool = new Pool({
    connectionString: databaseUrl,
    max: options.max ?? 20,
    idleTimeoutMillis: options.idleTimeoutMillis ?? 30_000,
    connectionTimeoutMillis: options.connectionTimeoutMillis ?? 5_000,
    ...(useSsl ? { ssl: { rejectUnauthorized: false } } : {}),
  });

  // -------------------------------------------------------------------------
  // Pool-level error handler
  // Catches errors on idle clients (e.g. unexpected disconnects from the
  // server) that would otherwise crash the Node process.
  // -------------------------------------------------------------------------
  pool.on('error', (err, client) => {
    console.error('[db] Unexpected error on idle client:', err.message);
    // Do NOT rethrow — the pool will issue a new connection on the next query.
    // If you use a structured logger (Winston, Pino, etc.) replace console.error.
  });

  // -------------------------------------------------------------------------
  // Optional lifecycle logging (useful during development / debugging)
  // -------------------------------------------------------------------------
  if (process.env.NODE_ENV !== 'production') {
    pool.on('connect', () => {
      console.debug('[db] New client connected to the pool.');
    });

    pool.on('acquire', () => {
      console.debug('[db] Client acquired from pool.');
    });

    pool.on('remove', () => {
      console.debug('[db] Client removed from pool.');
    });
  }

  return pool;
}

// ---------------------------------------------------------------------------
// Health check
// ---------------------------------------------------------------------------

/**
 * Verifies that the pool can acquire a client and execute a trivial query.
 *
 * @returns {Promise<{
 *   healthy: boolean,
 *   latencyMs: number,
 *   totalCount: number,
 *   idleCount: number,
 *   waitingCount: number,
 *   timestamp: string,
 *   error?: string
 * }>}
 *
 * @example
 * const result = await checkHealth();
 * // { healthy: true, latencyMs: 3, totalCount: 1, idleCount: 1, waitingCount: 0, timestamp: '...' }
 */
async function checkHealth() {
  const timestamp = new Date().toISOString();
  const activePool = pool ?? createPool();

  const start = Date.now();
  let client;

  try {
    client = await activePool.connect();
    await client.query('SELECT 1');
    const latencyMs = Date.now() - start;

    return {
      healthy: true,
      latencyMs,
      totalCount: activePool.totalCount,
      idleCount: activePool.idleCount,
      waitingCount: activePool.waitingCount,
      timestamp,
    };
  } catch (err) {
    return {
      healthy: false,
      latencyMs: Date.now() - start,
      totalCount: activePool?.totalCount ?? 0,
      idleCount: activePool?.idleCount ?? 0,
      waitingCount: activePool?.waitingCount ?? 0,
      timestamp,
      error: err.message,
    };
  } finally {
    // Always release the client back to the pool
    client?.release();
  }
}

// ---------------------------------------------------------------------------
// Graceful shutdown
// ---------------------------------------------------------------------------

/**
 * Drains the pool and closes all connections.
 * Call this during SIGTERM / SIGINT handling to avoid connection leaks.
 *
 * @returns {Promise<void>}
 */
async function closePool() {
  if (!pool) return;
  await pool.end();
  pool = null;
  console.info('[db] Connection pool closed.');
}

// Register automatic shutdown handlers so the pool is always cleaned up
// when the Node process exits gracefully.
