'use strict';

const { Pool } = require('pg');
const path = require('path');
const fs = require('fs');

// ---------------------------------------------------------------------------
// Environment loader
// ---------------------------------------------------------------------------

/**
 * Minimal, dependency-light .env file parser.
 * Reads key=value pairs into process.env without overwriting existing values.
 * Supports:
 *   - Blank lines and # comments
 *   - Optional surrounding quotes (single or double)
 *   - Inline comments after quoted values
 *
 * @param {string} envFilePath - Absolute or relative path to the .env file.
 * @returns {{ loaded: boolean, path: string, error?: string }}
 */
function loadEnv(envFilePath = path.resolve(process.cwd(), '.env.test')) {
  const absolutePath = path.resolve(envFilePath);

  if (!fs.existsSync(absolutePath)) {
    return { loaded: false, path: absolutePath, error: 'File not found' };
  }

  try {
    const raw = fs.readFileSync(absolutePath, 'utf8');
    let count = 0;

    for (const rawLine of raw.split('\n')) {
      const line = rawLine.trim();

      // Skip blank lines and comments
      if (!line || line.startsWith('#')) continue;

      const eqIndex = line.indexOf('=');
      if (eqIndex === -1) continue;

      const key = line.slice(0, eqIndex).trim();
      let value = line.slice(eqIndex + 1).trim();

      // Strip optional surrounding quotes and inline comments
      const quoteMatch = value.match(/^(['"])([\s\S]*?)\1/);
      if (quoteMatch) {
        value = quoteMatch[2];
      } else {
        // Remove trailing inline comment  (e.g.  value  # comment)
        const commentIdx = value.indexOf(' #');
        if (commentIdx !== -1) value = value.slice(0, commentIdx).trim();
      }

      // Never overwrite a value that was already set (e.g. by CI/CD)
      if (!Object.prototype.hasOwnProperty.call(process.env, key)) {
        process.env[key] = value;
        count++;
      }
    }

    return { loaded: true, path: absolutePath, varsLoaded: count };
  } catch (err) {
    return { loaded: false, path: absolutePath, error: err.message };
  }
}

// ---------------------------------------------------------------------------
// Pool factory
// ---------------------------------------------------------------------------

/** @type {Pool | null} */
let pool = null;

