/**
 * db.js — PostgreSQL connection pool module
 *
 * Reads DATABASE_URL from the .env.test file at runtime via dotenv and
 * exposes a pg Pool instance, connection error handling, and a health-check
 * function.  Credentials are never hard-coded; they are resolved entirely at
 * process start from the environment file.
 */

'use strict';

const path = require('path');
const { Pool } = require('pg');
const dotenv = require('dotenv');

// ---------------------------------------------------------------------------
// 1. Load environment variables from .env.test
//    Override any already-set variables so the test file always wins in this
//    module's context.
// ---------------------------------------------------------------------------
const envResult = dotenv.config({
  path: path.resolve(__dirname, '.env.test'),
  override: true,
});

if (envResult.error) {
  // Fatal: we cannot start without the env file.
  throw new Error(
    `[db] Failed to load .env.test: ${envResult.error.message}`
  );
}

// ---------------------------------------------------------------------------
// 2. Validate that DATABASE_URL is actually present after loading
// ---------------------------------------------------------------------------
const { DATABASE_URL } = process.env;

if (!DATABASE_URL) {
  throw new Error(
    '[db] DATABASE_URL is not defined. ' +
    'Ensure .env.test exists and contains a valid DATABASE_URL entry.'
  );
}

// ---------------------------------------------------------------------------
// 3. Build the connection pool
//    All options below are explicit so behaviour is predictable across
//    environments; tweak via additional env vars as needed.
// ---------------------------------------------------------------------------
const pool = new Pool({
  connectionString: DATABASE_URL,

  // Maximum number of clients kept alive in the pool.
  max: parseInt(process.env.DB_POOL_MAX ?? '10', 10),

  // Milliseconds a client must sit idle before being released.
  idleTimeoutMillis: parseInt(process.env.DB_IDLE_TIMEOUT_MS ?? '30000', 10),

  // Milliseconds to wait for a free client before throwing a timeout error.
  connectionTimeoutMillis: parseInt(
    process.env.DB_CONNECT_TIMEOUT_MS ?? '5000',
    10
  ),

  // Keep SSL config flexible: set DB_SSL=true to enable in production.
  ssl:
    process.env.DB_SSL === 'true'
      ? { rejectUnauthorized: process.env.DB_SSL_REJECT_UNAUTHORIZED !== 'false' }
      : false,
});

// ---------------------------------------------------------------------------
// 4. Pool-level error handler
//    Catches errors emitted by idle clients (e.g. unexpected server
//    disconnects).  Without this listener Node.js would throw an uncaught
//    exception and crash.
// ---------------------------------------------------------------------------
pool.on('error', (err, client) => {
  console.error('[db] Unexpected error on idle client:', err.message);
  // Do NOT call process.exit() here — let the application decide how to
  // handle pool errors (retry logic, graceful shutdown, etc.).
});

// ---------------------------------------------------------------------------
// 5. Pool lifecycle hooks (optional, useful for debugging)
// ---------------------------------------------------------------------------
pool.on('connect', () => {
  console.log('[db] New client connected to the pool.');
});

pool.on('acquire', () => {
  console.log('[db] Client acquired from the pool.');
});

pool.on('remove', () => {
  console.log('[db] Client removed from the pool.');
});

// ---------------------------------------------------------------------------
// 6. Health-check function
//    Acquires a client, runs a trivial query, and releases the client.
//    Resolves with a status object; never rejects — errors are captured and
//    returned as a failed-status object so callers can decide what to do.
// ---------------------------------------------------------------------------

/**
 * @typedef {Object} HealthCheckResult
 * @property {'ok'|'error'} status      - Overall result.
 * @property {number}       latencyMs   - Round-trip time for the test query.
 * @property {string}       [serverVersion] - PostgreSQL version string (on success).
 * @property {string}       [error]     - Error message (on failure).
 * @property {string}       timestamp   - ISO-8601 timestamp of the check.
 */

/**
 * Performs a lightweight database health check.
 *
 * @returns {Promise<HealthCheckResult>}
 *
 * @example
 * const result = await checkHealth();
 * // { status: 'ok', latencyMs: 4, serverVersion: '15.3', timestamp: '...' }
 */
async function checkHealth() {
  const start = Date.now();
  const timestamp = new Date().toISOString();

  let client;

  try {
    client = await pool.connect();

    // version() is available on every PostgreSQL server and is dirt cheap.
    const { rows } = await client.query(
      'SELECT version() AS server_version, NOW() AS server_time'
    );

    const latencyMs = Date.now() - start;
    const { server_version, server_time } = rows[0];

    return {
      status: 'ok',
      latencyMs,
      serverVersion: server_version,
      serverTime: server_time,
      timestamp,
    };
  } catch (err) {
    const latencyMs = Date.now() - start;
    console.error('[db] Health check failed:', err.message);

    return {
      status: 'error',
      latencyMs,
      error: err.message,
      timestamp,
    };
  } finally {
    // Always release the client back to the pool, even on error.
    if (client) client.release();
  }
}

// ---------------------------------------------------------------------------
// 7. Graceful shutdown helper
//    Call this during SIGTERM / SIGINT handlers to drain the pool cleanly.
// ---------------------------------------------------------------------------

/**
 * Drains the connection pool and closes all clients.
 * Should be called during graceful application shutdown.
 *
 * @returns {Promise<void>}
 *
 * @example
 * process.on('SIGTERM', async () => {
 *   await closePool();
 *   process.exit(0);
 * });
 */
async function closePool() {
  try {
    await pool.end();
    console.log('[db] Connection pool closed gracefully.');
  } catch (err) {
    console.error('[db] Error while closing the pool:', err.message);
    throw err;
  }
}

// ---------------------------------------------------------------------------
// 8. Exports
// ---------------------------------------------------------------------------
module.exports = {
  /**
   * The underlying pg Pool instance.
   * Use pool.query() for one-off queries or pool.connect() when you need
   * explicit transaction control.
   */
  pool,

  /**
   * Runs a lightweight SELECT against the database and returns a status
   * object.  Safe to expose behind an internal /health endpoint.
   */
  checkHealth,

  /**
   * Gracefully drains and closes the pool.  Call during process shutdown.
   */
  closePool,
};

